      if (has('error')) return 'error';   // the last good data (if any) still renders, with a「刷新失败」badge
      if (has('importing')) return 'importing';
      if (rs.some((r) => r.data == null && (r.state === 'loading' || r.state === 'idle'))) return 'loading';
      if (has('computing')) return rs.every((r) => r.data != null) ? 'stale' : 'computing';
      if (st.length && st.every((s) => s === 'empty')) return 'empty';
