      const res = {};
      descs.forEach((d) => {
        const r = C.resource(d.path, { scope: d.scope === false ? null : scope, query: d.query, waitMs: d.waitMs });
        res[d.name] = r;
        if (r.dirty && !r.loading) C.load(r, signal);
      });
      const rs = Object.keys(res).map((k) => res[k]);
      const state = aggregate(rs);
      const data = {}; rs.forEach((r, i) => { data[Object.keys(res)[i]] = r.data; });
      let vm = null, error = null;
      if (rs.every((r) => r.data != null)) { try { vm = b.toViewModel(data, { client: C, scope, res }); } catch (e) { error = { code: 'view_model', message: e.message }; } }
